class StokHabisError extends Error {
  constructor(public kode: string) {
    super(`Stok ${kode} habis`);
    this.name = "StokHabisError";
  }
}
class JumlahSalahError extends Error {
  constructor(public jumlah: number) {
    super(`Jumlah ${jumlah} tidak valid`);
    this.name = "JumlahSalahError";
  }
}
const stok: Record<string, number> = { P01: 12, P02: 0 };
function pesan(kode: string, jumlah: number): string {
  if (jumlah <= 0) throw new JumlahSalahError(jumlah);
  if ((stok[kode] ?? 0) < jumlah) throw new StokHabisError(kode);
  stok[kode] -= jumlah;
  return `OK ${kode} x${jumlah}`;
}
for (const [kode, jumlah] of [["P01", 2], ["P02", 1], ["P01", 0]] as const) {
  try {
    console.log(pesan(kode, jumlah));
  } catch (e) {
    if (e instanceof StokHabisError) console.log("Habis:", e.kode);
    else if (e instanceof Error) console.log(e.name);
  }
}

