class SaldoKurangError extends Error {
  constructor(public kurang: number) {
    super("Saldo kurang " + kurang);
    this.name = "SaldoKurangError";
  }
}
function bayar(saldo: number, total: number): number {
  if (total > saldo) throw new SaldoKurangError(total - saldo);
  return saldo - total;
}
console.log("Sisa:", bayar(100000, 80000));
try {
  console.log("Sisa:", bayar(50000, 80000));
} catch (e) {
  if (e instanceof SaldoKurangError) console.log("Kurang:", e.kurang);
  else if (e instanceof Error) console.log("Gagal:", e.message);
}

