class TidakAdaError extends Error {
  constructor(public id: string) {
    super("Tidak ada: " + id);
    this.name = "TidakAdaError";
  }
}
try {
  throw new TidakAdaError("U9");
} catch (e) {
  if (e instanceof TidakAdaError) console.log(e.name, e.id);
  if (e instanceof Error) console.log(e.message);
}

cards.solution:
class ValidasiError extends Error {
  constructor(public kolom: string) {
    super(kolom + " tidak valid");
    this.name = "ValidasiError";
  }
}
function cekEmail(email: string): string {
  if (!email.includes("@")) throw new ValidasiError("email");
  return email;
}
for (const email of ["rina@contoh.id", "rina.contoh.id"]) {
  try {
    console.log(cekEmail(email));
  } catch (e) {
    if (e instanceof ValidasiError) console.log(e.name, e.kolom);
  }
}
